query PageQuery(
  $slug: String!
  $after: String
) {
  ...LayoutFragment
  pageBySlug(slug: $slug) {
    id
    title
    slug
    content
    excerpt
    status
    publishedAt
    createdAt
    updatedAt
    defaultItemKind
  }
  pageItemsOfPage(where: {page: $slug}, first: 20, after: $after) {
    nodes {
      id
      title
      slug
      excerpt
      content
      status
      publishedAt
      author {
        displayName
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

fragment LayoutFragment on RootQuery {
  viewer {
    id
    displayName
    role
  }
  navigationPages: placedPages(where: {home: false}, first: 100) {
    nodes {
      id
      title
      slug
      accent
    }
  }
}

